const listViolationCategories = `-- name: ListViolationCategories :many
SELECT id, code, name, point, severity, description, is_active, created_at, updated_at
FROM violation_categories
WHERE (
    $1::TEXT = '' OR
    code ILIKE '%' || $1 || '%' OR
    name ILIKE '%' || $1 || '%' OR
    description ILIKE '%' || $1 || '%'
)
ORDER BY is_active DESC, severity, code
`

func (q *Queries) ListViolationCategories(ctx context.Context, search string) ([]ViolationCategory, error) {
	rows, err := q.db.Query(ctx, listViolationCategories, search)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ViolationCategory{}
	for rows.Next() {
		var i ViolationCategory
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.Point,
			&i.Severity,
			&i.Description,
			&i.IsActive,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

